// Hand-written. Not generated by Speakeasy.
//
// sensitive_test.go guards a list of attributes we already know about. That
// catches a regeneration dropping x-speakeasy-param-sensitive from one of
// them, which is what it was written for, and it cannot catch a secret
// arriving under a name nobody has thought of yet.
//
// It did not catch one. credential_request_encryption_jwks came in with the
// credential request encryption settings, held private keys by its own
// description, and printed them in plan output, in apply output and in
// terraform show, on the resource and on the data source. Being nested inside
// credential_issuer_metadata, it was out of reach of a guard that reads only
// the top level.
//
// So this guard works the other way round. It walks every attribute at every
// depth, and anything whose description says it holds private keys must be
// concealed. New attributes are covered the moment they appear, because the
// test is not told their names. An attribute that mentions private keys
// without holding any is exempted below, by name and with a reason, so that
// leaving one in the clear is a decision somebody wrote down.
package provider

import (
	"context"
	"strings"
	"testing"

	"github.com/hashicorp/terraform-plugin-framework/datasource"
	dschema "github.com/hashicorp/terraform-plugin-framework/datasource/schema"
	"github.com/hashicorp/terraform-plugin-framework/resource"
	rschema "github.com/hashicorp/terraform-plugin-framework/resource/schema"
)

// Attributes that mention private keys but carry none.
//
// Keyed by the path this test prints, so an exemption covers one attribute
// rather than every attribute sharing its name.
var notSecretDespiteDescription = map[string]string{
	"authlete_client.jwks":         `The spec says it "must not include private keys of the client application". Concealing a client's public set costs readability for no gain.`,
	"authlete_client.jwks_uri":     "A URL pointing at a client's public set, not key material.",
	"authlete_service.hsks[*].use": `Describes what a key on the HSM is used for ("sig" or "enc"). The key itself never leaves the HSM and is not in state.`,
}

func mentionsPrivateKeys(description string) bool {
	return strings.Contains(strings.ToLower(description), "private key")
}

func walkResourceAttrs(t *testing.T, prefix string, attrs map[string]rschema.Attribute) {
	t.Helper()
	for name, attr := range attrs {
		path := prefix + "." + name
		var nested map[string]rschema.Attribute
		switch a := attr.(type) {
		case rschema.SingleNestedAttribute:
			nested = a.Attributes
		case rschema.ListNestedAttribute:
			nested = a.NestedObject.Attributes
			path = prefix + "." + name + "[*]"
		case rschema.SetNestedAttribute:
			nested = a.NestedObject.Attributes
			path = prefix + "." + name + "[*]"
		case rschema.MapNestedAttribute:
			nested = a.NestedObject.Attributes
			path = prefix + "." + name + "[*]"
		}
		reportAttr(t, path, attr.GetDescription(), attr.IsSensitive())
		if nested != nil {
			walkResourceAttrs(t, path, nested)
		}
	}
}

func walkDataSourceAttrs(t *testing.T, prefix string, attrs map[string]dschema.Attribute) {
	t.Helper()
	for name, attr := range attrs {
		path := prefix + "." + name
		var nested map[string]dschema.Attribute
		switch a := attr.(type) {
		case dschema.SingleNestedAttribute:
			nested = a.Attributes
		case dschema.ListNestedAttribute:
			nested = a.NestedObject.Attributes
			path = prefix + "." + name + "[*]"
		case dschema.SetNestedAttribute:
			nested = a.NestedObject.Attributes
			path = prefix + "." + name + "[*]"
		case dschema.MapNestedAttribute:
			nested = a.NestedObject.Attributes
			path = prefix + "." + name + "[*]"
		}
		reportAttr(t, path, attr.GetDescription(), attr.IsSensitive())
		if nested != nil {
			walkDataSourceAttrs(t, path, nested)
		}
	}
}

func reportAttr(t *testing.T, path, description string, sensitive bool) {
	t.Helper()
	if !mentionsPrivateKeys(description) || sensitive {
		return
	}
	if _, exempt := notSecretDespiteDescription[path]; exempt {
		return
	}
	t.Errorf("%s says it holds private keys and is not marked sensitive, so it prints in "+
		"plan output, in apply output and in `terraform show`.\n\n"+
		"Mark it with `x-speakeasy-param-sensitive: true` in "+
		".speakeasy/terraform_overlay.yaml. If it carries no key material despite the "+
		"wording, add its path to notSecretDespiteDescription with the reason.\n\n"+
		"Description: %s", path, strings.TrimSpace(description))
}

func TestAttributesDescribedAsHoldingPrivateKeysAreConcealed(t *testing.T) {
	for name, res := range map[string]resource.Resource{
		"authlete_service": NewServiceResource(),
		"authlete_client":  NewClientResource(),
	} {
		walkResourceAttrs(t, name, resourceSchema(t, res).Attributes)
	}

	for name, ds := range map[string]datasource.DataSource{
		"authlete_service": NewServiceDataSource(),
		"authlete_client":  NewClientDataSource(),
	} {
		resp := &datasource.SchemaResponse{}
		ds.Schema(context.Background(), datasource.SchemaRequest{}, resp)
		if resp.Diagnostics.HasError() {
			t.Fatalf("%s data source schema has errors: %v", name, resp.Diagnostics)
		}
		walkDataSourceAttrs(t, name, resp.Schema.Attributes)
	}
}

// Every exemption must name an attribute that exists. Otherwise a renamed or
// removed attribute leaves a stale excuse behind that would silently cover a
// future attribute of the same name.
func TestExemptionsStillApplyToSomething(t *testing.T) {
	seen := map[string]bool{}
	var collect func(prefix string, attrs map[string]rschema.Attribute)
	collect = func(prefix string, attrs map[string]rschema.Attribute) {
		for name, attr := range attrs {
			path := prefix + "." + name
			var nested map[string]rschema.Attribute
			switch a := attr.(type) {
			case rschema.SingleNestedAttribute:
				nested = a.Attributes
			case rschema.ListNestedAttribute:
				nested = a.NestedObject.Attributes
				path += "[*]"
			case rschema.SetNestedAttribute:
				nested = a.NestedObject.Attributes
				path += "[*]"
			case rschema.MapNestedAttribute:
				nested = a.NestedObject.Attributes
				path += "[*]"
			}
			seen[path] = true
			if nested != nil {
				collect(path, nested)
			}
		}
	}
	collect("authlete_service", resourceSchema(t, NewServiceResource()).Attributes)
	collect("authlete_client", resourceSchema(t, NewClientResource()).Attributes)

	for path := range notSecretDespiteDescription {
		if !seen[path] {
			t.Errorf("notSecretDespiteDescription exempts %q, which no longer exists.\n\n"+
				"Remove the entry, or correct the path if the attribute was renamed.", path)
		}
	}
}
